wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(506381475077611298)
,p_plug_name=>'Iluminacoes'
,p_region_name=>'os_todos'
,p_parent_plug_id=>wwv_flow_imp.id(506381220742611296)
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(519416879738522989)
,p_plug_display_sequence=>30
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html CLOB := '''';',
'    v_tem_registro BOOLEAN := FALSE;',
'BEGIN',
'    v_html := v_html || ''',
'        <div class="iluminacao-list" ',
'             style="font-family:Arial, sans-serif;',
'                    max-height:500px;',
'                    overflow-y:auto;',
'                    border:1px solid #ddd;',
'                    border-radius:6px;">'';',
'',
'    FOR r IN (',
'        SELECT ',
'            MIN(i.cod_iluminacao) AS cod_iluminacao,',
'            i.processo_documento,',
'            i.solicitante_contato,',
'            i.cor,',
'            LISTAGG(DISTINCT NVL(i.evento, ''Sem evento informado''), '', '') ',
'                WITHIN GROUP (ORDER BY i.evento) AS eventos,',
'            LISTAGG(DISTINCT NVL(i.tipo, ''Sem tipo informado''), '', '') ',
'                WITHIN GROUP (ORDER BY i.tipo) AS tipos,',
'            MIN(i.dat_solicitacao) AS dat_solicitacao,',
'            MIN(i.dat_inicio) AS dat_inicio,',
'            MAX(i.dat_fim) AS dat_fim,',
unistr('            LISTAGG(DISTINCT NVL(i.noticias, ''Sem not\00EDcias''), ''<br>'') '),
'                WITHIN GROUP (ORDER BY i.noticias) AS noticias,',
'            LISTAGG(DISTINCT NVL(i.observacao, ''''), ''<br>'') ',
'                WITHIN GROUP (ORDER BY i.observacao) AS observacoes,',
unistr('            LISTAGG(DISTINCT NVL(i.autorizacao, ''N\00E3o informado''), ''<br>'') '),
'                WITHIN GROUP (ORDER BY i.autorizacao) AS autorizacoes',
'        FROM iluminacao i',
'        WHERE',
'            (',
'                :P1_COR IS NULL',
'                OR i.cor IN (',
'                    SELECT TRIM(COLUMN_VALUE)',
'                    FROM TABLE(apex_string.split(:P1_COR, '':''))',
'                )',
'            )',
'            AND (',
'                :P1_EVENTO IS NULL OR',
'                LOWER(TRANSLATE(i.evento,',
unistr('                    ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                    ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc''))',
'                LIKE ''%'' || LOWER(TRANSLATE(:P1_EVENTO,',
unistr('                    ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                    ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc'')) || ''%''',
'            )',
'            AND (:P1_TIPO IS NULL OR LOWER(i.tipo) = LOWER(:P1_TIPO))',
'            AND (',
'                (:P1_DAT_INICIO IS NULL AND :P1_DAT_FIM IS NULL)',
'                OR (:P1_DAT_INICIO IS NULL AND i.dat_inicio <= :P1_DAT_FIM)',
'                OR (:P1_DAT_FIM IS NULL AND i.dat_inicio >= :P1_DAT_INICIO)',
'                OR (i.dat_inicio BETWEEN :P1_DAT_INICIO AND :P1_DAT_FIM)',
'            )',
'            AND (:P1_PROCESSO IS NULL OR i.processo_documento LIKE :P1_PROCESSO || ''%'')',
'            AND (',
'                :P1_SOLICITANTE IS NULL OR',
'                LOWER(TRANSLATE(i.solicitante_contato,',
unistr('                    ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                    ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc''))',
'                = LOWER(TRANSLATE(:P1_SOLICITANTE,',
unistr('                    ''\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7'','),
'                    ''AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc''))',
'            )',
'            AND (:P1_AUTORIZACAO IS NULL OR LOWER(i.autorizacao) = LOWER(:P1_AUTORIZACAO))',
'        GROUP BY ',
'            i.processo_documento,',
'            i.solicitante_contato,',
'            i.cor',
'        ORDER BY MIN(i.dat_solicitacao) DESC, MIN(i.cod_iluminacao) DESC',
'    ) LOOP',
'        BEGIN',
'            v_tem_registro := TRUE;',
'',
'            v_html := v_html || ''',
'                <div class="iluminacao-item"',
'                     id="ilum_'' || TO_CHAR(r.cod_iluminacao) || ''" ',
'                     style="display:flex;',
'                            justify-content:space-between;',
'                            align-items:flex-start;',
'                            padding:12px;',
'                            border-bottom:1px solid #eee;',
'                            border-left:8px solid '' || ',
'                                CASE ',
'                                    WHEN r.cor = ''Roxo'' THEN ''#9b59b6'' ',
'                                    WHEN r.cor = ''Preto'' THEN ''#000000'' ',
'                                    WHEN r.cor = ''Azul'' THEN ''#3498db'' ',
'                                    WHEN r.cor = ''Verde'' THEN ''#2ecc71''',
'                                    WHEN r.cor = ''Amarelo'' THEN ''#f1c40f'' ',
'                                    WHEN r.cor = ''Rosa'' THEN ''#e91e63'' ',
'                                    WHEN r.cor = ''Vermelho'' THEN ''#e74c3c'' ',
'                                    WHEN r.cor = ''Cinza'' THEN ''#95a5a6'' ',
'                                    WHEN r.cor = ''Laranja'' THEN ''#e67e22'' ',
'                                    WHEN r.cor = ''Marrom'' THEN ''#8e5c42'' ',
unistr('                                    WHEN r.cor = ''Lil\00E1s'' THEN ''#b57edc'' '),
'                                    WHEN r.cor = ''Roxo Escuro'' THEN ''#4b0082'' ',
'                                    WHEN r.cor = ''Branco'' THEN ''#ffffff'' ',
'                                    ELSE ''#cccccc'' ',
'                                END || '';',
'                            border-radius:4px;">'';',
'',
'            v_html := v_html || ''',
'                <div class="iluminacao-content" style="flex:1;">',
'                    <div style="font-size:16px;',
'                                font-weight:bold;',
'                                color:#2c3e50;',
'                                margin-bottom:4px;',
'                                background-color:#e8f4fd;',
'                                padding:4px 8px;',
'                                border-radius:4px;',
'                                display:inline-block;">'' ',
'                        || NVL(r.eventos, ''Sem evento informado'') || ',
'                    ''</div>',
'',
'                    <div style="font-size:13px;color:#555;margin-top:2px;">',
'                        <b>Solicitante:</b> ',
'                        <span style="font-weight:bold;',
'                                     background-color:#f0f8ff;',
'                                     color:#2c3e50;',
'                                     padding:2px 6px;',
'                                     border-radius:4px;',
'                                     display:inline-block;">',
'                            '' || r.solicitante_contato || ''',
'                        </span><br>',
'                        <b>Processo:</b> '' || r.processo_documento || ''',
'                    </div>',
'',
'                    <div style="font-size:13px;color:#666;margin-top:6px;">',
'                        <b>Cor:</b> '' || r.cor || ''<br>',
'                        <b>Tipo(s):</b> '' || r.tipos || ''',
'                    </div>',
'',
'                    <div style="font-size:12px;color:#777;margin-top:6px;">',
unistr('                        <b>In\00EDcio:</b> '' || TO_CHAR(r.dat_inicio, ''DD/MM/YYYY'') || '),
'                        '' &nbsp;&nbsp; <b>Fim:</b> '' || TO_CHAR(r.dat_fim, ''DD/MM/YYYY'') || ''',
'                    </div>',
'',
'                    <div style="font-size:12px;color:#888;margin-top:6px;">',
unistr('                        <b>Autoriza\00E7\00E3o:</b><br>'' || NVL(r.autorizacoes, ''\2014'') || '''),
'                    </div>',
'',
'                    <div style="font-size:12px;color:#888;margin-top:6px;">',
unistr('                        <b>Not\00EDcias:</b><br>'' || NVL(r.noticias, ''Sem not\00EDcias'') || '''),
'                    </div>',
'',
'                    <div style="font-size:12px;color:#888;margin-top:6px;">',
unistr('                        <b>Observa\00E7\00F5es:</b><br>'' || NVL(r.observacoes, '''') || '''),
'                    </div>',
'                </div>',
'',
'                <div style="font-size:20px;color:#bbb;margin-left:10px;"> ',
'                    <a class="iluminacao-link" ',
'                       href="'' || APEX_PAGE.GET_URL(',
'                            p_page => 1,',
'                            p_items => ''P1_ID_ILU'',',
'                            p_values => r.cod_iluminacao',
'                        ) || ''">&rsaquo;</a>',
'                </div>',
'            </div>'';',
'        END;',
'    END LOOP;',
'',
'    IF NOT v_tem_registro THEN',
'        v_html := v_html || ''',
'            <div style="padding:20px;',
'                        text-align:center;',
'                        color:#888;',
'                        font-style:italic;">',
unistr('                Nenhum registro de Ilumina\00E7\00E3o encontrado.'),
'            </div>'';',
'    END IF;',
'',
'    v_html := v_html || ''</div>'';',
'',
'    RETURN v_html;',
'END;',
''))
,p_lazy_loading=>true
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P1_COR,P1_EVENTO,P1_TIPO,P1_DAT_INICIO,P1_DAT_FIM,P1_PROCESSO,P1_SOLICITANTE,P1_AUTORIZACAO'
);
