wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(520894424093552423)
,p_plug_name=>'Detalhes'
,p_region_name=>'Detalhes'
,p_parent_plug_id=>wwv_flow_imp.id(520895160995552430)
,p_region_css_classes=>'detalhes-altos'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(519416879738522989)
,p_plug_display_sequence=>40
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_tipo              iluminacao.tipo%TYPE;',
'    v_dat_solicitacao   iluminacao.dat_solicitacao%TYPE;',
'    v_solicitante       iluminacao.solicitante_contato%TYPE;',
'    v_processo          iluminacao.processo_documento%TYPE;',
'    v_autorizacao       iluminacao.autorizacao%TYPE;',
'    v_evento            iluminacao.evento%TYPE;',
'    v_dat_inicio        iluminacao.dat_inicio%TYPE;',
'    v_dat_fim           iluminacao.dat_fim%TYPE;',
'    v_noticias          iluminacao.noticias%TYPE;',
'    v_observacao        iluminacao.observacao%TYPE;',
'    v_cor               iluminacao.cor%TYPE;',
'    v_html              CLOB := '''';',
'BEGIN',
'    SELECT ',
'        tipo,',
'        dat_solicitacao,',
'        solicitante_contato,',
'        processo_documento,',
'        autorizacao,',
'        evento,',
'        dat_inicio,',
'        dat_fim,',
'        noticias,',
unistr('        NVL(observacao, ''N\00E3o h\00E1.''),'),
'        cor',
'    INTO ',
'        v_tipo,',
'        v_dat_solicitacao,',
'        v_solicitante,',
'        v_processo,',
'        v_autorizacao,',
'        v_evento,',
'        v_dat_inicio,',
'        v_dat_fim,',
'        v_noticias,',
'        v_observacao,',
'        v_cor',
'    FROM iluminacao',
'    WHERE cod_iluminacao = :P1_ID_ILU;',
'',
'    -- Layout em duas colunas',
'    v_html := v_html || ''<div style="display:flex;justify-content:space-between;gap:40px;">'';',
'',
'    -- Coluna esquerda',
'    v_html := v_html || ''<div style="flex:1;">'' ||',
unistr('                       ''<div><b>Tipo</b><br>''||NVL(v_tipo, ''N\00E3o informado'')||''</div><br>'' ||'),
unistr('                       ''<div><b>Solicitante/Contato</b><br>''||NVL(v_solicitante, ''N\00E3o informado'')||''</div><br>'' ||'),
unistr('                       ''<div><b>Processo/Documento</b><br>''||NVL(v_processo, ''N\00E3o informado'')||''</div><br>'' ||'),
unistr('                       ''<div><b>Autoriza\00E7\00E3o</b><br>''||NVL(v_autorizacao, ''N\00E3o informado'')||''</div><br>'' ||'),
unistr('                       ''<div><b>Evento</b><br>''||NVL(v_evento, ''N\00E3o informado'')||''</div><br>'' ||'),
'                       ''</div>'';',
'',
'    -- Coluna direita',
'    v_html := v_html || ''<div style="flex:1;">'' ||',
unistr('                       ''<div><b>Data de Solicita\00E7\00E3o</b><br>''||'),
'                       TO_CHAR(v_dat_solicitacao, ''DD/MM/YYYY HH24:MI'')||''</div><br>'' ||',
unistr('                       ''<div><b>Data de In\00EDcio</b><br>''||'),
'                       TO_CHAR(v_dat_inicio, ''DD/MM/YYYY'')||''</div><br>'' ||',
'                       ''<div><b>Data de Fim</b><br>''||',
'                       TO_CHAR(v_dat_fim, ''DD/MM/YYYY'')||''</div><br>'' ||',
unistr('                       ''<div><b>Cor</b><br>''||NVL(v_cor, ''N\00E3o especificada'')||''</div><br>'' ||'),
unistr('                       ''<div><b>Not\00EDcias</b><br>''||NVL(v_noticias, ''N\00E3o h\00E1 not\00EDcias'')||''</div><br>'' ||'),
unistr('                       ''<div><b>Observa\00E7\00E3o</b><br>''||v_observacao||''</div><br>'' ||'),
'                       ''</div>'';',
'',
'    v_html := v_html || ''</div>'';',
'',
'    RETURN v_html;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN ''',
'            <div style="padding:20px;',
'                        text-align:center;',
'                        color:#888;',
'                        font-style:italic;',
'                        font-family:Arial, sans-serif;',
'                        border:1px solid #ddd;',
'                        border-radius:6px;',
'                        background-color:#fafafa;">',
unistr('                Selecione um registro de Ilumina\00E7\00E3o.'),
'            </div>'';',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P1_ID_ILU'
);
