'if (id_os) {',
'    var target = document.getElementById(''ilum_'' + id_os);',
'    if (target) {',
'        var corEl = target.querySelector(''.iluminacao-cor'');',
'        var corNome = corEl ? corEl.textContent.replace(''Cor:'', '''').trim().toLowerCase() : '''';',
'        ',
'        // Tabela de cores para destaque',
'        var cores = {',
'            ''roxo'': ''#9b59b6'',',
'            ''preto'': ''#000000'',',
'            ''azul'': ''#3498db'',',
'            ''verde'': ''#2ecc71'',',
'            ''amarelo'': ''#f1c40f'',',
'            ''rosa'': ''#e91e63'',',
'            ''vermelho'': ''#e74c3c'',',
'            ''cinza'': ''#95a5a6'',',
'            ''laranja'': ''#e67e22'',',
'            ''marrom'': ''#8e5c42'',',
unistr('            ''lil\00E1s'': ''#b57edc'','),
'            ''roxo escuro'': ''#4b0082'',',
'            ''branco'': ''#ffffff''',
'        };',
'        ',
'        var corFundo = cores[corNome] || ''#cce5ff'';',
'        ',
unistr('        // Faz rolar at\00E9 o item e destaca suavemente'),
'        target.scrollIntoView({ behavior: ''smooth'', block: ''center'' });',
