unistr('        target.style.backgroundColor = corFundo + ''33''; // vers\00E3o transl\00FAcida'),
'        ',
'        setTimeout(function() {',
'            target.style.transition = ''background-color 2s ease'';',
'            target.style.backgroundColor = '''';',
'        }, 1500);',
'    }',
'}',
''))
);
