,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_count NUMBER := 0;',
'BEGIN',
'  IF :P2_NUM_OS IS NULL THEN',
'    :P2_CRIADO := ''N'';',
'    RETURN;',
'  END IF;',
'',
'  BEGIN',
'    SELECT COUNT(*) INTO v_count',
'    FROM ordens_servicos',
'    WHERE num_os = :P2_NUM_OS;',
'  EXCEPTION WHEN OTHERS THEN',
'    v_count := 0;',
'  END;',
'',
'  IF v_count > 0 THEN',
'    :P2_CRIADO := ''S'';',
'  ELSE',
'    :P2_CRIADO := ''N'';',
'  END IF;',
'END;',
''))
,p_attribute_02=>'P2_NUM_OS'
,p_attribute_03=>'P2_CRIADO'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
